const p = $('Prepare public context').first().json;
const candidate = $json.candidates?.[0];
const reply = candidate?.finishReason === 'STOP' ? (candidate.content?.parts || []).filter(part => !part.thought && typeof part.text === 'string').map(part => part.text).join('').trim() : '';
return [{json:{...p,reply}}];
